import re
xml = open('word/document.xml').read()
def walk(body):
    i=0; out=[]
    while True:
        pp=body.find('<w:p ',i); pt=body.find('<w:tbl>',i)
        if pp==-1 and pt==-1: break
        if pt!=-1 and (pp==-1 or pt<pp):
            e=body.find('</w:tbl>',pt)+9; out.append(('TBL',pt,e)); i=e
        else:
            e=body.find('</w:p>',pp)+6; out.append(('P',pp,e)); i=e
    return out
s = xml.find('<w:body>')
els = walk(xml[s:])
def txt(e): return ''.join(re.findall(r'<w:t[^>]*>([^<]*)</w:t>', e))
out=[]
for k,a,b in els:
    e = xml[s+a:s+b]
    t = txt(e)
    if k=='TBL':
        out.append('[TABLE]')
        rows = re.findall(r'<w:tr[ >].*?</w:tr>', e, re.S)
        for r in rows:
            cells = re.findall(r'<w:tc>.*?</w:tc>', r, re.S)
            ctext = [''.join(re.findall(r'<w:t[^>]*>([^<]*)</w:t>', c)) for c in cells]
            out.append(' | '.join(ctext))
        out.append('[/TABLE]')
    else:
        if t.strip(): out.append(t)
open('doc_full.txt','w').write('\n'.join(out))
print(len(out))
"

