import json, urllib.request, urllib.error, sys, re, concurrent.futures as cf, copy
sys.path.insert(0,'.')
from providers import config, credential, tls_context, payload_for, parse_response
from cases import CASES
from workflow import make_state
cfg=config(); key=credential("llm",cfg,"gateway")
base=(cfg.get("CLAUDE_GATEWAY_BASE_URL") or cfg.get("ANTHROPIC_BASE_URL") or cfg.get("LLM_BASE_URL")).rstrip("/")
ep=(base if base.endswith("/v1") else base+"/v1")+"/messages"; ctx=tls_context(cfg)
model, variant = sys.argv[1], sys.argv[2]
def call(body, extra={}):
    h={"Content-Type":"application/json","Authorization":"Bearer "+key,"anthropic-version":"2023-06-01",**extra}
    req=urllib.request.Request(ep,data=json.dumps(body).encode(),headers=h,method="POST")
    try: return json.loads(urllib.request.urlopen(req,context=ctx,timeout=120).read())
    except urllib.error.HTTPError as e: return {"HTTP":e.code,"body":e.read(400).decode(errors="replace")}
def go(c):
    body=payload_for("llm",make_state(c),model,"anthropic"); extra={}
    if variant=="bogus": body["output_config"]["format"]={"type":"nonsense"}
    if variant=="tool":
        schema=body["output_config"].pop("format")["schema"]
        body["tools"]=[{"name":"record_judgments","description":"Record the eight judgments.","strict":True,"input_schema":schema}]
        body["tool_choice"]={"type":"auto"}
        body["system"]+= "\nReturn your answer only by calling the record_judgments tool."
        if not body["output_config"]: body.pop("output_config")
    r=call(body,extra)
    if "HTTP" in r: return f"HTTP {r['HTTP']} {r['body'][:200]}"
    if variant=="tool":
        tu=[b for b in r.get("content",[]) if b.get("type")=="tool_use"]
        return "ok" if tu and set(tu[0]["input"])==set(json.loads(json.dumps(tu[0]["input"]))) and len(tu[0]["input"])==8 else f"no tool: {r.get('stop_reason')} {str(r.get('content'))[:150]}"
    try: json.loads("".join(b.get("text","") for b in r["content"] if b.get("type")=="text")); return "ok"
    except Exception: return "non-json"
n=int(sys.argv[3]) if len(sys.argv)>3 else 16
with cf.ThreadPoolExecutor(16) as ex: rs=list(ex.map(go,CASES[:n]))
import collections; print(model,variant,collections.Counter(r[:120] for r in rs))
EOF
