    $('.st-money .r3').classList.toggle('off', !posted.checked);
    $('#r3note').textContent = posted.checked ? 'accepted through CDRN' : 'announced by CDRN, not yet in the ledger';
    const v = -184 + (step >= 2 && pc.checked ? 184 : 0) + (step >= 3 && posted.checked ? 184 : 0);
    $('#bal').textContent = fmt(v);
    $('#balNote').textContent = v < 0 ? 'out of pocket' : v === 0 ? 'made whole' : 'credited twice';
    const b = $('#balance');
    b.classList.toggle('even', v === 0); b.classList.toggle('twice', v > 0);
  }
  pc.addEventListener('change', render); posted.addEventListener('change', render);
  return { step(k) { step = k; if (k < 4) { pc.checked = true; posted.checked = true; } render(); } };
})();

/* ------------------------------------------------------------------ 2.2 loop */
const loop = (() => {
  const inPC = $('#inPC'), inRefund = $('#inRefund'), inFound = $('#inFound'), inThr = $('#inThr');
  const STEP_MS = 3800, END_MS = 3000;
  let path = [], i = 0, playing = true, timer = null, active = false;

  function build() {
    const thr = +inThr.value, P = [];
    const jev = (state, q, opts, ruleOk, ruleLow, extra = {}) => {
      const top = opts[0][1], ok = top >= thr;
      return { state, who: 'jev', q, opts, ok, rule: ok ? ruleOk : ruleLow, res: ok ? 'auto' : 'person', ...extra };
    };
    P.push(jev('ALERT_CREATED', 'Dispute reason',
      [['Duplicate processing', .91], ['Paid by other means', .05], ['Incorrect amount', .03], ['Late presentment', .01]],
      'Confident · participating merchant → send to CDRN', 'Below threshold → an analyst confirms the reason, then CDRN',
      { chip: 'reason · duplicate' }));
    if (!inRefund.checked) {
      P.push({ state: 'AWAITING_MERCHANT', who: 'code', q: 'Merchant response', kv: ['CDRN status', 'DECLINED'],
        rule: 'Declined → decide the next action', res: 'next', chip: 'merchant declined' });
      P.push(jev('AWAITING_MERCHANT', 'Next action',
        [['recommend_dispute_handoff_review', .94], ['inconclusive', .04], ['recommend_case_close_review', .02]],
        'Confident → hand off to the formal dispute process', 'Below threshold → a person decides',
        { out: 'HANDOFF', chip: 'handoff' }));
      return P;
    }
    P.push({ state: 'AWAITING_MERCHANT', who: 'code', q: 'Merchant response', kv: ['Outcome code', '100 · full credit'],
      rule: 'Full credit → watch the ledger for the refund', res: 'next', chip: 'outcome 100' });
    if (!inFound.checked) {
      P.push({ ...jev('AWAITING_REFUND_OBSERVATION', 'Which ledger credit is the merchant refund?',
        [['None of these', .71], ['€184.00 · Transfer · 13 Mar', .21], ['€50.00 · HOTEL LISBOA · 15 Mar', .08]],
        '', ''), rule: 'No match → keep watching until the observation window ends', res: 'next', chip: 'no match' });
      P.push({ state: 'AWAITING_REFUND_OBSERVATION', who: 'code', q: 'Observation window', kv: ['Window', 'ended · no refund observed'],
        rule: 'No refund in time → exception for a person', res: 'person', out: 'EXCEPTION', chip: 'window ended' });
      return P;
    }
    P.push(jev('AWAITING_REFUND_OBSERVATION', 'Which ledger credit is the merchant refund?',
      [['€184.00 · HTL LISBOA REF · 14 Mar', .93], ['€184.00 · Transfer · 13 Mar', .04], ['€50.00 · HOTEL LISBOA · 15 Mar', .02], ['None of these', .01]],
      'Confident → link the refund automatically', 'Below threshold → an analyst confirms the match',
      { chip: 'refund matched' }));
    const net = inPC.checked ? 184 : 0;
    P.push({ state: 'RECONCILING', who: 'code', q: 'Net position of the cardholder',
      calc: [['Original charge', -184, true], ['Provisional credit', 184, inPC.checked], ['Merchant refund', 184, true]], net,
      rule: net > 0 ? 'Credited twice → double credit candidate' : 'Balanced → nothing to correct', res: 'next',
      chip: net > 0 ? 'net +€184' : 'net €0' });
    if (net > 0) {
      P.push({ ...jev('RECONCILING', 'Next action',
        [['recommend_pc_reversal', .89], ['recommend_offset_review', .06], ['inconclusive', .05]], '', ''),
        rule: 'Moves money → a person always approves', res: 'person', out: 'FINANCIAL_ACTION_REVIEW', chip: 'pc reversal' });
    } else {
      P.push(jev('RECONCILING', 'Next action',
        [['confirm_observed_refund_match', .95], ['recommend_case_close_review', .03], ['inconclusive', .02]],
        'No money moves · confident → close automatically', 'Below threshold → a person reviews, then close',
        { out: 'CLOSED', chip: 'confirm match' }));
    }
    return P;
  }

  const eur = v => (v < 0 ? '−€' : '+€') + Math.abs(v);
  function card(s) {
    const thr = +inThr.value;
    let body = '';
    if (s.opts) body = `<div class="opts">${s.opts.map(([l, p], k) =>
      `<div class="op${k === 0 ? ' top' : ''}${k === 0 && s.res === 'person' && s.who === 'jev' && !s.out ? ' low' : ''}"><code>${l}</code>
        <span class="tr"><i style="--w:${p * 100}%"></i>${k === 0 ? `<span class="thr" style="--thr:${thr * 100}%"></span>` : ''}</span>
        <span class="pv">${p.toFixed(2)}</span></div>`).join('')}</div>`;
    if (s.kv) body = `<div class="kv"><span>${s.kv[0]}</span><b>${s.kv[1]}</b></div>`;
    if (s.calc) body = `<div class="calc">${s.calc.map(([l, v, on]) => `<div class="${on ? '' : 'off'}"><span>${l}</span><span>${eur(v)}</span></div>`).join('')}
      <div class="sum${s.net > 0 ? ' twice' : ''}"><span>Net position</span><span>${s.net > 0 ? '+€' + s.net : '€0'}</span></div></div>`;
    const resLabel = { auto: '✓ automatic', person: '👤 person', next: '→ next' }[s.res];
    const who = { jev: 'Jev', code: 'Code', person: 'Person' }[s.who];
    return `<div class="dh"><span class="role ${s.who}">${who}</span><code>${s.state}</code></div>
      <h3>${s.q}</h3>${body}
      <div class="rule"><span>${s.rule}</span><span class="res ${s.res}">${resLabel}</span></div>`;
  }

  function place() {
    const s = path[i], track = $('#track');
    $$('.tn', track).forEach(n => {
      const idx = path.findIndex(p => p.state === n.dataset.s);
      const last = path.map(p => p.state).lastIndexOf(n.dataset.s);
      n.classList.toggle('on', n.dataset.s === s.state && !s.out);
      n.classList.toggle('done', idx > -1 && idx <= i && !(n.dataset.s === s.state && !s.out));
    });
    $$('.to', track).forEach(o => o.classList.toggle('on', !!s.out && o.dataset.o === s.out));
    const target = s.out ? $(`.to[data-o=${s.out}]`, track) : $(`.tn[data-s=${s.state}]`, track);
    const tb = track.getBoundingClientRect(), b = target.getBoundingClientRect();
    const puck = $('#lPuck');
    puck.style.left = (s.out ? b.left - tb.left - 10 : b.left - tb.left + b.width / 2) + 'px';
    puck.style.top = (s.out ? b.top - tb.top + b.height / 2 : b.bottom - tb.top) + 'px';
  }

  function render() {
    const s = path[i], dc = $('#dcard');
    dc.innerHTML = card(s);
    dc.classList.remove('swap'); void dc.offsetWidth; dc.classList.add('swap');
    const counts = { auto: 0, person: 0, code: 0 };
    path.slice(0, i + 1).forEach(p => { if (p.who === 'code' && p.res !== 'person') counts.code++; else if (p.res === 'person') counts.person++; else counts.auto++; });
    $('#trail').innerHTML = path.slice(0, i + 1).map((p, k) =>
      `<span class="chip${k === i ? ' cur' : ''}"><i class="dotr ${p.res === 'person' ? 'person' : p.who}"></i>${k + 1} · ${p.chip}</span>`).join('') +
      (s.out ? `<span class="summary"><b>${counts.auto}</b> Jev automatic · <b>${counts.code}</b> code · <b>${counts.person}</b> person</span>` : '');
    $('#lPos').textContent = `${i + 1} / ${path.length}`;
    place();
  }

  function schedule() {
    clearTimeout(timer);
    if (!playing || !active) return;
    const last = i === path.length - 1;
    timer = setTimeout(() => { i = last ? 0 : i + 1; render(); schedule(); }, last ? END_MS + STEP_MS : STEP_MS);
  }
  function go(d) { i = Math.max(0, Math.min(path.length - 1, i + d)); render(); schedule(); }
  function setPlay(p) { playing = p; $('#lPlay').textContent = p ? '❚❚' : '▶'; schedule(); }
  function rebuild(keepPos) {
    path = build();
    i = keepPos ? Math.min(i, path.length - 1) : 0;
    $('#inThrV').textContent = (+inThr.value).toFixed(2);
    render(); schedule();
  }

  $('#lPrev').addEventListener('click', () => go(-1));
  $('#lNext').addEventListener('click', () => go(1));
  $('#lPlay').addEventListener('click', () => setPlay(!playing));
  [inPC, inRefund, inFound].forEach(x => x.addEventListener('change', () => rebuild(false)));
  inThr.addEventListener('input', () => rebuild(true));
  addEventListener('resize', () => path.length && place());
  rebuild(false);

  return {
    enter() { active = true; place(); schedule(); },
    leave() { active = false; clearTimeout(timer); },
    key(e) {
      if (e.key === 'ArrowRight') { go(1); return true; }
      if (e.key === 'ArrowLeft') { go(-1); return true; }
      if (e.key === 'p' || e.key === 'P') { setPlay(!playing); return true; }
      return false;
    },
  };
})();

/* ------------------------------------------------------------------ 2.3 system stream */
const system = (() => {
  const canvas = $('#sysCanvas'), ctx = canvas.getContext('2d');
  const sPC = $('#sPC'), sThr = $('#sThr'), sPolicy = $('#sPolicy');
  let W = 0, H = 0, parts = [], raf = 0, last = 0, acc = 0, seed = 3;
  const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
  // Illustrative mix: 12% merchant declines, 6% no refund observed, rest refunded.
  const conf = () => 1 - 0.35 * Math.pow(rnd(), 2.2);
  function route(pcShare, thr, policy) {
    const r = rnd();
    if (r < 0.12) return 'hand';
    if (r < 0.18) return 'person';
    if (conf() < thr) return 'person';
    const pc = rnd() < pcShare;
    if (pc) return policy ? 'person' : (conf() >= thr ? 'auto' : 'person');
    return conf() >= thr ? 'auto' : 'person';
  }
  function stats() {
    const pcShare = sPC.value / 100, thr = +sThr.value, policy = sPolicy.checked;
    $('#sPCV').textContent = sPC.value + '%';
    $('#sThrV').textContent = thr.toFixed(2);
    const save = seed; seed = 99; const n = 6000, c = { auto: 0, person: 0, hand: 0 };
    for (let k = 0; k < n; k++) c[route(pcShare, thr, policy)]++;
    seed = save;
    $('#cAuto').textContent = Math.round(c.auto / n * 100) + '%';
    $('#cPerson').textContent = Math.round(c.person / n * 100) + '%';
    $('#cHand').textContent = Math.round(c.hand / n * 100) + '%';
  }
  [sPC, sThr].forEach(x => x.addEventListener('input', stats));
  sPolicy.addEventListener('change', stats);

  function size() {
    const b = canvas.getBoundingClientRect(), dpr = devicePixelRatio || 1;
    W = b.width; H = b.height; canvas.width = W * dpr; canvas.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  const COL = { auto: '#1F9D6B', person: '#F2B01E', hand: '#1434CB' };
  const ease = x => x < .5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
  function frame(now) {
    const dt = Math.min(now - (last || now), 50); last = now; acc += dt;
    const pcShare = sPC.value / 100, thr = +sThr.value, policy = sPolicy.checked;
    while (acc > 45) { acc -= 45; parts.push({ x: 0, j: (rnd() - .5) * 30, j2: (rnd() - .5) * 18, v: .12 + rnd() * .05, to: route(pcShare, thr, policy) }); }
    const nx = W * .34, cy = H / 2, ty = { auto: H * .2, person: H * .5, hand: H * .8 }, endX = W - 220;
    ctx.clearRect(0, 0, W, H);
    parts = parts.filter(p => p.x < endX);
    for (const p of parts) {
      p.x += p.v * dt;
      let y, col;
      if (p.x < nx) { y = cy + p.j * (1 - p.x / nx); col = 'rgba(91,100,120,.45)'; }
      else { const k = ease(Math.min((p.x - nx) / (endX - nx) * 1.4, 1)); y = cy + (ty[p.to] - cy + p.j2) * k; col = COL[p.to]; }
      ctx.beginPath(); ctx.arc(p.x, y, 3.4, 0, 7); ctx.fillStyle = col; ctx.fill();
    }
    raf = requestAnimationFrame(frame);
  }
  stats();
  return {
    enter() { size(); cancelAnimationFrame(raf); last = 0; raf = requestAnimationFrame(frame); },
    leave() { cancelAnimationFrame(raf); },
  };
})();

