/* ================================================================== PART 3 */

/* ------------------------------------------------------------------ 3.1 paragraph vs one word */
const duel = (() => {
  const text = "Thanks for the details. Looking at this case, the cardholder appears to have been billed twice by the same merchant, for the same amount and on the same date. This would typically be classified as a processing error, most likely duplicate processing, although it may be worth confirming the merchant did not issue two separate charges before proceeding.";
  const LLM_MS = 8566, JEV_MS = 114; // TypeSafe's side-by-side demo timings
  const stream = $('#p31Stream'), ans = $('#p31Ans'), t1 = $('#p31T1'), t2 = $('#p31T2');
  let raf = 0, tid = 0;
  function reset() {
    cancelAnimationFrame(raf); clearTimeout(tid);
    const words = text.split(' ');
    stream.className = 'p3-stream';
    stream.innerHTML = words.map((w, i) => {
      const key = (w === 'processing' && words[i + 1] === 'error,') || w === 'error,';
      return `<span${key ? ' class="key"' : ''}>${w} </span>`;
    }).join('');
    ans.classList.remove('in'); t1.textContent = t2.textContent = '0.00 s';
  }
  function run() {
    reset();
    const spans = $$('span', stream), start = performance.now();
    tid = setTimeout(() => { ans.classList.add('in'); t2.textContent = (JEV_MS / 1000).toFixed(2) + ' s'; }, JEV_MS);
    let shown = 0;
    const tick = now => {
      const el = Math.min(now - start, LLM_MS);
      const target = Math.floor(el / LLM_MS * spans.length);
      while (shown < target) spans[shown++].classList.add('in');
      t1.textContent = (el / 1000).toFixed(2) + ' s';
      if (el >= LLM_MS) { spans.forEach(s => s.classList.add('in')); tid = setTimeout(() => stream.classList.add('done'), 400); return; }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  }
  $('#p31Run').addEventListener('click', run);
  reset();
  return { enter() {}, leave: reset, key(e) { if (e.key === 'ArrowRight' || e.key === 'Enter') { run(); return true; } return false; } };
})();

/* ------------------------------------------------------------------ 3.2 eight questions */
const race = (() => {
  const QS = [
    ['Recognises the transaction?', '0.96'], ['Dispute category', 'processing error'], ['Reason', 'duplicate'], ['Evidence attached?', '0.97'],
    ['Merchant replied?', '0.92'], ['Which credit is the refund?', 'HTL LISBOA'], ['Next action', 'reverse credit'], ['Frustration', '1.3 / 2'],
  ];
  const LLM_MS = 10100, JEV_MS = 400; // TypeSafe benchmark, per case
  const html = QS.map(([q, a]) => `<div class="p3-row"><span class="q">${q}</span><span class="a">${a}</span><i class="p"></i></div>`).join('');
  $('#p32L').innerHTML = html; $('#p32J').innerHTML = html;
  const L = $$('#p32L .p3-row'), J = $$('#p32J .p3-row');
  let raf = 0;
  function paint(el) {
    const jp = Math.min(el / JEV_MS, 1), slot = LLM_MS / QS.length;
    J.forEach(r => { $('.p', r).style.width = jp * 100 + '%'; r.classList.toggle('done', jp >= 1); });
    L.forEach((r, i) => { const p = Math.max(0, Math.min((el - i * slot) / slot, 1)); $('.p', r).style.width = p * 100 + '%'; r.classList.toggle('done', p >= 1); });
    $('#p32T2').textContent = (Math.min(el, JEV_MS) / 1000).toFixed(1) + ' s';
    $('#p32T1').textContent = (Math.min(el, LLM_MS) / 1000).toFixed(1) + ' s';
  }
  function reset() { cancelAnimationFrame(raf); paint(0); }
  function run() {
    reset(); const start = performance.now();
    const tick = now => { const el = now - start; paint(el); if (el < LLM_MS) raf = requestAnimationFrame(tick); };
    raf = requestAnimationFrame(tick);
  }
  $('#p32Run').addEventListener('click', run);
  reset();
  return { enter() {}, leave: reset, key(e) { if (e.key === 'ArrowRight' || e.key === 'Enter') { run(); return true; } return false; } };
})();

/* ------------------------------------------------------------------ 3.3 price × threshold */
const price = (() => {
  const canvas = $('#p33Canvas'), ctx = canvas.getContext('2d'), thr = $('#p33Thr');
  const C_JEV = 0.0004, C_LLM = 0.1761; // $ per case, TypeSafe benchmark
  let seed = 11; const rnd = () => { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
  const SAMPLE = Array.from({ length: 6000 }, () => 1 - 0.5 * Math.pow(rnd(), 2.3)); // illustrative, skewed high
  let W = 0, H = 0, parts = [], raf = 0, last = 0, acc = 0;
  const money = v => v >= 1e3 ? '$' + (v / 1e3).toFixed(v >= 1e4 ? 0 : 1) + 'K' : '$' + v.toFixed(0);
  function stats() {
    const t = +thr.value;
    $('#p33ThrV').textContent = t.toFixed(2);
    const auto = SAMPLE.filter(c => c >= t), share = auto.length / SAMPLE.length;
    const err = auto.reduce((a, c) => a + (1 - c), 0) / Math.max(auto.length, 1);
    $('#p33Auto').textContent = Math.round(share * 100) + '%';
    $('#p33Err').textContent = (err * 100).toFixed(1) + '%';
    const all = 1e6 * C_LLM, jev = 1e6 * (C_JEV + (1 - share) * C_LLM);
    $('#p33All').textContent = money(all); $('#p33Jev').textContent = money(jev);
    $('#p33BarJev').style.width = jev / all * 100 + '%';
  }
  thr.addEventListener('input', stats);
  function size() {
    const b = canvas.getBoundingClientRect(), dpr = devicePixelRatio || 1;
    W = b.width; H = b.height; canvas.width = W * dpr; canvas.height = H * dpr; ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }
  const ease = x => x < .5 ? 2 * x * x : 1 - Math.pow(-2 * x + 2, 2) / 2;
  function frame(now) {
    const dt = Math.min(now - (last || now), 50); last = now; acc += dt;
    while (acc > 30) { acc -= 30; parts.push({ x: 0, j: (rnd() - .5) * 26, j2: (rnd() - .5) * 28, c: SAMPLE[(rnd() * SAMPLE.length) | 0], v: .16 + rnd() * .06 }); }
    const t = +thr.value, jx = W * .38, cy = H / 2, yT = H * .24, yB = H * .78;
    ctx.clearRect(0, 0, W, H);
    parts = parts.filter(p => p.x < W + 10);
    for (const p of parts) {
      p.x += p.v * dt;
      let y, col;
      if (p.x < jx) { y = cy + p.j * (1 - p.x / jx); col = 'rgba(91,100,120,.45)'; }
      else { const up = p.c >= t, k = ease(Math.min((p.x - jx) / (W - jx) * 1.6, 1)); y = cy + ((up ? yT : yB) - cy + p.j2) * k; col = up ? '#1434CB' : '#F2B01E'; }
      ctx.beginPath(); ctx.arc(p.x, y, 3.2, 0, 7); ctx.fillStyle = col; ctx.fill();
    }
    raf = requestAnimationFrame(frame);
  }
  stats();
  return { enter() { size(); cancelAnimationFrame(raf); last = 0; raf = requestAnimationFrame(frame); }, leave() { cancelAnimationFrame(raf); } };
})();

